// spec: .qa/e2e/specs/tender-actions.md
// seed: tests/seed.company.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });

const T25 = 'מנהלי/ות מרכזי קבלה בבתי מלון';
const RENEW_NOTE = /אפשר לחדש את הפרסום/;

test.describe('Tender owner actions (company)', () => {
  test('Expired tender: bell «אפשר לחדש את הפרסום» leads to a working renewal dialog (no renewal) @desktop @prod-safe #cf6dc1', async ({ page }) => {
    // 1. «המכרזים שלי» → bell «התראות»
    await page.goto('/tenders?mine=1');
    await page.getByRole('button', { name: /^התראות/ }).click();
    const bell = page.getByRole('dialog', { name: 'התראות' });
    await expect(bell).toBeVisible();

    // 2. Notification «…הסתיים ולא מוצג יותר. אפשר לחדש את הפרסום.» — T-25 preferred
    const renewNotes = bell.getByRole('link', { name: RENEW_NOTE });
    const t25Note = renewNotes.filter({ hasText: T25 });
    let title = T25;
    if (await t25Note.count()) {
      await t25Note.first().click();
    } else if (await renewNotes.count()) {
      title = (await renewNotes.first().innerText()).match(/„([^”]+)”/)![1];
      test.info().annotations.push({ type: 'note', description: `No bell notification for T-25; used the renewal notification of «${title}» instead` });
      await renewNotes.first().click();
    } else {
      test.info().annotations.push({ type: 'note', description: 'No «אפשר לחדש את הפרסום» notification in the bell; opened T-25 from «המכרזים שלי»' });
      await page.keyboard.press('Escape');
      await page.getByRole('link', { name: `לפרטי המכרז: ${T25}` }).click();
    }

    // Expected: «פרטי המכרז» of the expired tender: «פג תוקף», «המכרז הסתיים ב-<date> ולא מוצג יותר.», «חידוש הפרסום»
    const details = page.getByRole('dialog', { name: 'פרטי המכרז' });
    await expect(details.getByRole('heading', { level: 3, name: title, exact: true })).toBeVisible();
    await expect(details.getByText('פג תוקף', { exact: true })).toBeVisible();
    const endedText = details.getByText(/^המכרז הסתיים ב-\d{2}\.\d{2}\.\d{4} ולא מוצג יותר\.$/);
    await expect(endedText).toBeVisible();
    const endDate = (await endedText.innerText()).match(/\d{2}\.\d{2}\.\d{4}/)![0];
    if (title === T25) expect(endDate).toBe('16.10.2026');
    await expect(details).toContainText(new RegExp(`תאריך תוקף\\s*${endDate.replace(/\./g, '\\.')}`));

    // 3. «חידוש הפרסום»
    await details.getByRole('button', { name: 'חידוש הפרסום' }).click();
    const renew = page.getByRole('dialog', { name: 'חידוש הפרסום' });
    await expect(renew).toBeVisible();
    await expect(renew.getByText(title, { exact: true })).toBeVisible();
    await expect(renew.getByText(`המכרז הסתיים ב-${endDate}`, { exact: true })).toBeVisible();
    await expect(renew.getByText('תאריך תוקף חדש *', { exact: true })).toBeVisible();
    await expect(renew.getByRole('textbox', { name: /^תאריך תוקף חדש/ })).toBeVisible();
    await expect(renew.getByRole('group', { name: 'סוג הפרסום' }).getByRole('radio')).toHaveCount(2);
    await expect(renew.getByRole('radio', { name: 'מכרז רגיל ללא עלות' })).toBeChecked();
    await expect(renew.getByRole('radio', { name: 'מכרז חם ₪1,500' })).not.toBeChecked();
    await expect(renew.getByRole('button', { name: 'אישור' })).toBeVisible();

    // 4. «לא תודה» — nothing renewed
    await renew.getByRole('button', { name: 'לא תודה' }).click();
    await expect(renew).toBeHidden();
    await expect(details.getByText('פג תוקף', { exact: true })).toBeVisible();
  });
});
